import {requireVendor} from '@/lib/auth/vendor';import {createClient} from '@/lib/supabase/server';import {createCsv,csvResponse} from '@/lib/csv';
export async function GET(){const context=await requireVendor(),db=await createClient();const{data,error}=await db.from('order_items').select('product_name,options,quantity,line_total,suborder:restaurant_orders(status,delivery_fee,platform_commission,seller_net_amount,restaurant_id,order:orders(reference,created_at,customer_name,customer_phone,fulfillment,commune,address,payment_status))').eq('suborder.restaurant_id',context.restaurant!.id).limit(5000);if(error)throw error;const rows=(data??[]).flatMap(item=>{const sub=Array.isArray(item.suborder)?item.suborder[0]:item.suborder;if(!sub||sub.restaurant_id!==context.restaurant!.id)return[];const order=Array.isArray(sub.order)?sub.order[0]:sub.order;if(!order)return[];return[[order.reference,order.created_at,order.customer_name,order.customer_phone,order.fulfillment,order.commune,order.address,item.product_name,Array.isArray(item.options)?item.options.map((o:{name?:string})=>o.name).filter(Boolean).join(', '):'',item.quantity,item.line_total,sub.delivery_fee,sub.status,order.payment_status,sub.platform_commission,sub.seller_net_amount]]});return csvResponse(createCsv(['Référence','Date','Client','Téléphone','Mode','Zone','Adresse','Produit','Options','Quantité','Montant ligne','Livraison','Statut commande','Statut paiement','Commission','Net vendeur'],rows),`mes-commandes-${new Date().toISOString().slice(0,10)}.csv`)}
